# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İNSANIN ALLAH (CC) İLE İRTİBAT YOLLARI: DUA VE İBADET</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. DUA: KULUN RABBİNE YÖNELİŞİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Sözlükte: Çağırmak, seslenmek, yardım dilemek</text>\n  <text x="35" y="110" font-size="11.2" fill="#1e3a8a">• Kavram olarak: Kulun acziyetini bilerek Yüce Allah\'a</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">  halini arz etmesi ve O\'ndan hayır istemesidir.</text>\n  <text x="35" y="150" font-size="11.2" fill="#1e3a8a">• Kavli Dua: Dil ve kalple yapılan niyaz ve yakarış</text>\n  <text x="35" y="172" font-size="11.2" fill="#1e3a8a">• Fiili Dua: Sebeplere sarılarak emek ve çaba gösterme</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. İBADET: KULLUK BİLİNCİ VE İTAAT</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Sözlükte: Boyun eğmek, tevazu ve itaat etmek</text>\n  <text x="370" y="110" font-size="11.2" fill="#14532d">• Kavram olarak: Allah\'ın rızasını kazanmak için emirlerini</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">  yerine getirip yasaklarından kaçınmaktır (Zâriyât, 56).</text>\n  <text x="370" y="150" font-size="11.2" fill="#14532d">• İhlas (samimiyet) ve Sünnete uygunluk temel şarttır.</text>\n  <text x="370" y="172" font-size="11.2" fill="#14532d">• Namaz, oruç, zekât ve hac kulluk bağını diri tutar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«De ki: Duanız olmasa Rabbim size ne diye değer versin!» (Furkân suresi, 77. ayet)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÖVBE-İSTİĞFAR VE KUR\'AN OKUMA (TİLAVET VE TEDEBÜR)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">3. TÖVBE VE İSTİĞFAR: ÖZE DÖNÜŞ</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Tövbe: Günahtan pişman olup Allah\'a dönmek</text>\n  <text x="35" y="110" font-size="11.2" fill="#713f12">• İstiğfar: Günahın bağışlanmasını (mağfiret) dilemek</text>\n  <text x="35" y="132" font-size="11.2" fill="#713f12">• Nasuh Tövbesi: İçten, samimi ve kesin kararlı tövbe</text>\n  <text x="35" y="154" font-size="11.2" fill="#713f12">• Şartları: Günahı terk etmek, pişmanlık duymak,</text>\n  <text x="35" y="172" font-size="11.2" fill="#713f12">  bir daha dönmemeye azmetmek ve kul hakkını ödemek</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">4. KUR\'AN OKUMA (KIRAAT - TİLAVET - TERTİL)</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Kur\'an, Yüce Allah\'ın insanlığa gönderdiği son ilahi</text>\n  <text x="370" y="106" font-size="11.2" fill="#581c87">  hitaptır; onu okumak Rabbiyle konuşmak gibidir.</text>\n  <text x="370" y="128" font-size="11.2" fill="#581c87">• Tertil: Harflerin hakkını vererek tane tane okumak</text>\n  <text x="370" y="150" font-size="11.2" fill="#581c87">• Tedebbür ve Tefekkür: Ayetlerin anlamını derinlemesine</text>\n  <text x="370" y="168" font-size="11.2" fill="#581c87">  düşünmek ve mesajlarını hayata aktarmaktır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Dua ve ibadet kuldan Allah\'a yükselen niyaz, Kur\'an-ı Kerim ise Allah\'tan kula inen ilahi kelamdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MARİFETULLAH, ESMÂ-İ HÜSNÂ VE ALLAH-İNSAN İRTİBATININ BÜTÜNLÜĞÜ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MARİFETULLAH VE ESMÂ-İ HÜSNÂ İLE DUA</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Marifetullah: Allah\'ı varlık delilleri (gaye ve nizam)</text>\n  <text x="35" y="106" font-size="11.2" fill="#7c2d12">  ve güzel isimleriyle (Esmâ-i Hüsnâ) hakkıyla tanımak</text>\n  <text x="35" y="128" font-size="11.2" fill="#7c2d12">• «En güzel isimler Allah\'ındır; O\'na o güzel isimleriyle</text>\n  <text x="35" y="146" font-size="11.2" fill="#7c2d12">  dua edin.» (A\'râf suresi, 180. ayet)</text>\n  <text x="35" y="168" font-size="11.2" fill="#7c2d12">• Tevvâb, الغَفَّارُ (Gaffâr), الرَّحْمٰنُ (Rahmân), السَّمِيعُ (Semî\')</text>\n  <text x="35" y="184" font-size="11.2" fill="#7c2d12">  ve الْمُجِيبُ (Mucîb) isimleri irtibatın dayanağıdır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">İRTİBAT YOLLARININ AHLAKİ SONUÇLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• Dua → Ümit (recâ), tevekkül ve iç huzuru kazandırır.</text>\n  <text x="370" y="112" font-size="11.2" fill="#164e63">• İbadet → Kötülüklerden alıkoyar, sorumluluk bilinci verir.</text>\n  <text x="370" y="136" font-size="11.2" fill="#164e63">• Tövbe → Ümitsizliği önler, nefsi arındırır ve yeniler.</text>\n  <text x="370" y="160" font-size="11.2" fill="#164e63">• Kur\'an Okuma → Hidayet, hikmet ve doğru istikamet sunar.</text>\n  <text x="370" y="184" font-size="11.2" font-weight="bold" fill="#155e75">• İhsan Bilinci: Allah\'ı görüyormuşçasına yaşamak</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Allah (cc) insana şah damarından daha yakındır (Kâf, 16) ve kendisine yönelen kulunun duasına icabet eder (Bakara, 186).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
